def transform(grid):
    """Copy the one populated motif panel into every equally sized panel."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_divs = [r for r, row in enumerate(grid)
                if len(set(row)) == 1 and row[0] != bg]
    col_divs = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def segments(n, divs):
        out, start = [], 0
        for d in divs:
            if d > start:
                out.append(list(range(start, d)))
            start = d + 1
        if start < n:
            out.append(list(range(start, n)))
        return out

    rs, cs = segments(h, row_divs), segments(w, col_divs)
    if not rs or not cs:
        return [row[:] for row in grid]
    # The panels are congruent; the panel with the most non-background cells
    # (excluding the divider color) contains the motif to propagate.
    panels = [(sum(grid[r][c] != bg for r in rr for c in cc), rr, cc)
              for rr in rs for cc in cs]
    _, src_r, src_c = max(panels, key=lambda x: x[0])
    motif = [[grid[r][c] for c in src_c] for r in src_r]
    result = [row[:] for row in grid]
    for rr in rs:
        for cc in cs:
            if len(rr) != len(src_r) or len(cc) != len(src_c):
                continue
            for i, r in enumerate(rr):
                for j, c in enumerate(cc):
                    result[r][c] = motif[i][j]
    return result

if __name__ == '__main__':
    test = [[5,5,5],[5,5,5],[8,8,8],[7,7,5],[5,4,5]]
    print(transform(test))
